CREATE TABLE admins(id INTEGER PRIMARY KEY CHECK(id=1), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE admin_sessions(session_hash TEXT PRIMARY KEY, admin_id INTEGER NOT NULL REFERENCES admins(id) ON DELETE CASCADE, csrf_token TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, last_seen_at TEXT NOT NULL);
CREATE INDEX sessions_expiry ON admin_sessions(expires_at);
CREATE TABLE nodes(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, remark TEXT NOT NULL DEFAULT '', protocol TEXT NOT NULL, original_uri TEXT NOT NULL, normalized_config TEXT NOT NULL CHECK(json_valid(normalized_config)), unknown_params TEXT NOT NULL CHECK(json_valid(unknown_params)), parser_name TEXT NOT NULL, parser_version TEXT NOT NULL, parse_warnings TEXT NOT NULL CHECK(json_valid(parse_warnings)), unsupported_fields TEXT NOT NULL CHECK(json_valid(unsupported_fields)), tags TEXT NOT NULL CHECK(json_valid(tags)), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, remark TEXT NOT NULL DEFAULT '', token_hash TEXT NOT NULL UNIQUE, token_ciphertext TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE subscription_nodes(subscription_id INTEGER NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE, node_id INTEGER NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, position INTEGER NOT NULL CHECK(position>=0), created_at TEXT NOT NULL, PRIMARY KEY(subscription_id,node_id), UNIQUE(subscription_id,position));
CREATE INDEX node_references ON subscription_nodes(node_id);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT NOT NULL CHECK(json_valid(value)));
